extension Substring {
  fileprivate func byAddingGroupSeparators(at interval: Int) -> String {
    var result = ""
    result.reserveCapacity(self.count)
    for (i, char) in self.filter({ $0 != "_" }).reversed().enumerated() {
      if i > 0 && i % interval == 0 {
        result.append("_")
      }
      result.append(char)
    }
    return String(result.reversed())
  }
}
}

